#!/bin/bash
# scripts/run_js_zs.sh
#
# Zero-shot JS Similarity for the Phase 1 (pre-trained, NOT fine-tuned)
# checkpoint on the bar 3-4-5 infilling task.
#
# Consumes samples generated by slurm/generate_samples_zs.sh and runs the
# standard model_agg + js_score pipeline.

set -euo pipefail

# ── Paths ────────────────────────────────────────────────────────────────────
SAMPLES=/nfsd/tesi/zanettisim/MIDIT/outputs/samples_zs_1000
OUTPUTS=/nfsd/tesi/zanettisim/MIDIT/outputs

REF_AGG="$OUTPUTS/ref_agg.json"
MODEL_AGG="$OUTPUTS/model_agg_zs.json"
JS_OUT="$OUTPUTS/js_score_zs.json"

# ── Sanity ───────────────────────────────────────────────────────────────────
if [ ! -d "$SAMPLES" ]; then
    echo "Error: SAMPLES dir not found: $SAMPLES" >&2
    echo "       Run slurm/generate_samples_zs.sh first." >&2
    exit 1
fi

n_seeds=$(find "$SAMPLES" -maxdepth 1 -type d -name 'seed_*' | wc -l)
if [ "$n_seeds" -lt 100 ]; then
    echo "Error: $SAMPLES contains only $n_seeds seed_* directories (need >= 100)." >&2
    echo "       Wait for slurm/generate_samples_zs.sh to finish or re-run it." >&2
    exit 1
fi
echo "Found $n_seeds seed_* directories in $SAMPLES"

if [ ! -f "$REF_AGG" ]; then
    echo "Error: reference aggregate not found: $REF_AGG" >&2
    echo "       Run compute_reference_agg.py first." >&2
    exit 1
fi

# ── Activate venv ────────────────────────────────────────────────────────────
source .venv/bin/activate

# ── 1. Compute model aggregate over zero-shot samples ────────────────────────
echo "[1/2] Running compute_model_agg.py"
python -u scripts/Evaluation_Infilling/Matteo/compute_model_agg.py \
    --samples_dir "$SAMPLES" \
    --output_json "$MODEL_AGG" \
    --max_files   1000
echo

# ── 2. Compute JS similarity score ───────────────────────────────────────────
echo "[2/2] Running compute_js_score.py"
python -u scripts/Evaluation_Infilling/Matteo/compute_js_score.py \
    --model_agg   "$MODEL_AGG" \
    --ref_agg     "$REF_AGG" \
    --model_name  "MIDIT_ZS" \
    --output_json "$JS_OUT"
echo

# ── Final score ──────────────────────────────────────────────────────────────
js=$(python -c "import json,sys; print(json.load(open('$JS_OUT'))['js_similarity'])")
echo "════════════════════════════════════════════════════════════════"
echo "  MIDIT Zero-Shot JS Similarity = $js"
echo "════════════════════════════════════════════════════════════════"
